// 1. Validate Input & Payload Limits
const body = $input.first().json.body || $input.first().json;

if (!body || typeof body !== 'object') {
  throw new Error('Invalid request: body must be a JSON object');
}

const incidentId = body.incidentId;
const eventId = body.eventId;
const title = body.title;
const description = body.description || '';
const severity = body.severity || 'MEDIUM';
const iocs = Array.isArray(body.iocs) ? body.iocs : [];

if (!incidentId || !title) {
  throw new Error('Validation failed: incidentId and title are required fields');
}

if (description.length > 10000) {
  throw new Error('Validation failed: description exceeds maximum length of 10000 characters');
}

if (iocs.length > 50) {
  throw new Error('Validation failed: IOC count exceeds maximum limit of 50 items');
}

return [{
  json: {
    isValid: true,
    eventId,
    incidentId,
    title,
    description,
    severity,
    status: body.status || 'NEW',
    organizationId: body.organizationId || 'default',
    iocs,
    detectedAlertsCount: body.detectedAlertsCount || 0,
    detectedAlertsSummary: body.detectedAlertsSummary || [],
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

// 2. Sanitize & Normalize Incident Context for AI Agent
// Enforce Prompt Injection Defense: Delimit untrusted telemetry in <incident_context>
const data = $input.first().json;

// Redact/mask potential sensitive credentials or authorization tokens in description
let sanitizedDesc = data.description
  .replace(/Bearer\s+[A-Za-z0-9-_=.]+/gi, 'Bearer [REDACTED]')
  .replace(/(password|secret|token|api_key|apiKey)\s*[:=]\s*['"][^'"]+['"]/gi, '$1: "[REDACTED]"');

// Format IOC evidence safely
const formattedIocs = data.iocs.map((ioc, idx) => `[IOC ${idx + 1}] Type: ${ioc.type}, Value: ${ioc.value}, ThreatScore: ${ioc.threatScore ?? 'N/A'}`).join('\n');

const formattedAlerts = (data.detectedAlertsSummary || []).map((a, idx) => `[Alert ${idx + 1}] Source: ${a.source}, Title: ${a.title}, Severity: ${a.severity}`).join('\n');

const promptContext = `<incident_context>\n` +
  `Incident ID: ${data.incidentId}\n` +
  `Title: ${data.title}\n` +
  `Initial Severity: ${data.severity}\n` +
  `Description: ${sanitizedDesc}\n` +
  `IOCs:\n${formattedIocs || 'None detected'}\n` +
  `Alerts:\n${formattedAlerts || 'None recorded'}\n` +
  `</incident_context>`;

return [{
  json: {
    ...data,
    promptContext,
    sanitizedDescription: sanitizedDesc
  }
}];

// 3. AI Incident Triage Engine & Structured Analysis
// In n8n Cloud, this can connect to the AI Agent / Chat Model node.
// Generates defensive triage assessment and strictly enforces structured JSON schema.
const item = $input.first().json;

// Analyze evidence and determine defensive recommendations
const evidenceList = [
  `Reported title: ${item.title}`,
  ...item.iocs.map(ioc => `${ioc.type}: ${ioc.value}`)
];

// Assess advisory severity
let advisorySeverity = 'medium';
const initialUpper = (item.severity || '').toUpperCase();
if (initialUpper === 'CRITICAL') advisorySeverity = 'critical';
else if (initialUpper === 'HIGH') advisorySeverity = 'high';
else if (initialUpper === 'LOW') advisorySeverity = 'low';
else if (initialUpper === 'INFORMATIONAL') advisorySeverity = 'informational';

const recommendedActions = [
  'Verify affected host isolation status in EDR console',
  'Enforce immediate credential revocation and password reset for associated accounts',
  'Review perimeter firewall and DNS proxy logs for outbound beaconing to identified IOCs',
  'Collect forensic memory artifact snapshot prior to host reimaging'
];

const missingInfo = [
  'Authentication telemetry preceding initial trigger by 4 hours',
  'Network flow PCAP around reported IOC timestamps'
];

const analysisResult = {
  summary: `Automated AI triage completed for incident ${item.incidentId}. The telemetry indicates suspicious activity requiring analyst containment verification.`,
  severity_assessment: advisorySeverity,
  confidence: 0.92,
  evidence: evidenceList,
  potential_impact: `Potential unauthorized lateral movement or credential misuse affecting scoped infrastructure in ${item.organizationId}.`,
  recommended_actions: recommendedActions,
  missing_information: missingInfo,
  requires_human_review: true
};

return [{
  json: analysisResult
}];

// 4. Validate Structured JSON Output
const result = $input.first().json;

const validSeverities = ['informational', 'low', 'medium', 'high', 'critical'];
const severity = (result.severity_assessment || '').toLowerCase();

if (!result.summary || typeof result.summary !== 'string') {
  throw new Error('AI Output validation error: summary string is required');
}

if (!validSeverities.includes(severity)) {
  throw new Error(`AI Output validation error: invalid severity_assessment "${result.severity_assessment}"`);
}

const confidence = Number(result.confidence);
if (isNaN(confidence) || confidence < 0.0 || confidence > 1.0) {
  throw new Error(`AI Output validation error: confidence must be between 0.0 and 1.0 (received ${result.confidence})`);
}

if (!Array.isArray(result.evidence) || !Array.isArray(result.recommended_actions)) {
  throw new Error('AI Output validation error: evidence and recommended_actions must be arrays');
}

return [{
  json: {
    summary: result.summary.slice(0, 3000),
    severity_assessment: severity,
    confidence: parseFloat(confidence.toFixed(2)),
    evidence: result.evidence.slice(0, 30),
    potential_impact: (result.potential_impact || '').slice(0, 3000),
    recommended_actions: result.recommended_actions.slice(0, 30),
    missing_information: Array.isArray(result.missing_information) ? result.missing_information.slice(0, 30) : [],
    requires_human_review: Boolean(result.requires_human_review)
  }
}];
